-- Knotia v1.0.0 database setup
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,display_name text not null,email text not null,role text not null default 'member' check(role in('admin','member')),status text not null default 'pending' check(status in('pending','approved','rejected','suspended')),review_reason text,reviewed_at timestamptz,terms_version text,privacy_version text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.board_posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id),body text not null check(char_length(body) between 1 and 500),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.direct_messages(id uuid primary key default gen_random_uuid(),sender_id uuid not null references public.profiles(id),receiver_id uuid not null references public.profiles(id),body text not null check(char_length(body) between 1 and 2000),created_at timestamptz not null default now(),read_at timestamptz,check(sender_id<>receiver_id));
create table if not exists public.shared_notes(id uuid primary key default gen_random_uuid(),title text not null check(char_length(title) between 1 and 120),body text not null default '',created_by uuid not null references public.profiles(id),updated_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),is_deleted boolean not null default false,deleted_by uuid references public.profiles(id),deleted_at timestamptz);
create table if not exists public.note_revisions(id uuid primary key default gen_random_uuid(),note_id uuid not null references public.shared_notes(id) on delete cascade,title text not null,body text not null,editor_id uuid not null references public.profiles(id),created_at timestamptz not null default now(),action text not null default 'edit');
create table if not exists public.shared_links(id uuid primary key default gen_random_uuid(),title text not null,url text not null check(url~*'^https?://'),description text not null default '',category text not null default 'その他',created_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null,body text not null,type text not null default 'info',is_read boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.admin_logs(id bigint generated always as identity primary key,admin_id uuid not null references public.profiles(id),action text not null,target_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists dm_sender_idx on public.direct_messages(sender_id,created_at desc);create index if not exists dm_receiver_idx on public.direct_messages(receiver_id,created_at desc);create index if not exists board_created_idx on public.board_posts(created_at);create index if not exists notify_user_idx on public.notifications(user_id,is_read,created_at desc);
create or replace function public.is_approved(uid uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=uid and status='approved')$$;
create or replace function public.is_admin(uid uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=uid and role='admin' and status='approved')$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,full_name,display_name,email,terms_version,privacy_version) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.raw_user_meta_data->>'display_name','利用者'),coalesce(new.email,''),new.raw_user_meta_data->>'terms_version',new.raw_user_meta_data->>'privacy_version');return new;end$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.review_application(target_user uuid,new_status text,reason_text text default '') returns void language plpgsql security definer set search_path=public as $$begin if not is_admin() then raise exception 'admin only';end if;if new_status not in('approved','rejected','suspended') then raise exception 'invalid status';end if;update profiles set status=new_status,review_reason=reason_text,reviewed_at=now(),updated_at=now() where id=target_user;insert into notifications(user_id,title,body,type) values(target_user,case when new_status='approved' then '利用申請が承認されました' when new_status='rejected' then '利用申請の確認結果' else 'アカウント状態のお知らせ' end,case when new_status='approved' then 'Knotiaを利用できるようになりました。' when new_status='rejected' then '今回は利用を承認できませんでした。' else 'アカウントは現在利用停止中です。' end,'account');insert into admin_logs(admin_id,action,target_id,details) values(auth.uid(),'review_application',target_user::text,jsonb_build_object('status',new_status,'reason',reason_text));end$$;
create or replace function public.update_shared_note(note_id uuid,new_title text,new_body text) returns void language plpgsql security definer set search_path=public as $$declare n shared_notes;begin if not is_approved() then raise exception 'approved only';end if;select * into n from shared_notes where id=note_id and not is_deleted for update;if not found then raise exception 'not found';end if;insert into note_revisions(note_id,title,body,editor_id,action) values(n.id,n.title,n.body,auth.uid(),'edit');update shared_notes set title=new_title,body=new_body,updated_by=auth.uid(),updated_at=now() where id=note_id;end$$;
create or replace function public.trash_shared_note(note_id uuid) returns void language plpgsql security definer set search_path=public as $$begin if not is_approved() then raise exception 'approved only';end if;update shared_notes set is_deleted=true,deleted_by=auth.uid(),deleted_at=now(),updated_at=now() where id=note_id;insert into note_revisions(note_id,title,body,editor_id,action) select id,title,body,auth.uid(),'trash' from shared_notes where id=note_id;end$$;
create or replace function public.restore_shared_note(note_id uuid) returns void language plpgsql security definer set search_path=public as $$begin if not is_approved() then raise exception 'approved only';end if;update shared_notes set is_deleted=false,deleted_by=null,deleted_at=null,updated_by=auth.uid(),updated_at=now() where id=note_id;insert into note_revisions(note_id,title,body,editor_id,action) select id,title,body,auth.uid(),'restore' from shared_notes where id=note_id;end$$;
create or replace function public.restore_note_revision(revision_id uuid) returns void language plpgsql security definer set search_path=public as $$declare r note_revisions;declare n shared_notes;begin if not is_approved() then raise exception 'approved only';end if;select * into r from note_revisions where id=revision_id;select * into n from shared_notes where id=r.note_id for update;insert into note_revisions(note_id,title,body,editor_id,action) values(n.id,n.title,n.body,auth.uid(),'before_restore');update shared_notes set title=r.title,body=r.body,updated_by=auth.uid(),updated_at=now() where id=n.id;end$$;

create or replace function public.update_my_display_name(new_display_name text) returns void language plpgsql security definer set search_path=public as $$begin if auth.uid() is null then raise exception 'login required';end if;if char_length(trim(new_display_name)) not between 1 and 40 then raise exception 'invalid display name';end if;update profiles set display_name=trim(new_display_name),updated_at=now() where id=auth.uid();end$$;
create or replace function public.send_admin_notification(target_user uuid,notice_title text,notice_body text) returns void language plpgsql security definer set search_path=public as $$begin if not is_admin() then raise exception 'admin only';end if;if target_user is null then insert into notifications(user_id,title,body,type) select id,notice_title,notice_body,'admin' from profiles where status='approved';else insert into notifications(user_id,title,body,type) values(target_user,notice_title,notice_body,'admin');end if;insert into admin_logs(admin_id,action,target_id,details) values(auth.uid(),'send_notification',coalesce(target_user::text,'all'),jsonb_build_object('title',notice_title));end$$;
alter table profiles enable row level security;alter table board_posts enable row level security;alter table direct_messages enable row level security;alter table shared_notes enable row level security;alter table note_revisions enable row level security;alter table shared_links enable row level security;alter table notifications enable row level security;alter table admin_logs enable row level security;
create policy "own or approved profiles" on profiles for select to authenticated using(id=auth.uid() or (is_approved() and status='approved') or is_admin());
create policy "approved board read" on board_posts for select to authenticated using(is_approved());create policy "approved board insert" on board_posts for insert to authenticated with check(is_approved() and author_id=auth.uid());create policy "own or admin board delete" on board_posts for delete to authenticated using(author_id=auth.uid() or is_admin());
create policy "dm parties read" on direct_messages for select to authenticated using(is_approved() and (sender_id=auth.uid() or receiver_id=auth.uid()));create policy "dm sender insert" on direct_messages for insert to authenticated with check(is_approved() and sender_id=auth.uid() and exists(select 1 from profiles p where p.id=receiver_id and p.status='approved'));
create policy "approved notes read" on shared_notes for select to authenticated using(is_approved());create policy "approved notes insert" on shared_notes for insert to authenticated with check(is_approved() and created_by=auth.uid() and updated_by=auth.uid());create policy "approved revisions read" on note_revisions for select to authenticated using(is_approved());
create policy "approved links read" on shared_links for select to authenticated using(is_approved());create policy "approved links insert" on shared_links for insert to authenticated with check(is_approved() and created_by=auth.uid());create policy "own links delete" on shared_links for delete to authenticated using(created_by=auth.uid() or is_admin());
create policy "own notifications" on notifications for select to authenticated using(user_id=auth.uid());create policy "own notifications update" on notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "admin logs read" on admin_logs for select to authenticated using(is_admin());
grant execute on function review_application(uuid,text,text) to authenticated;grant execute on function update_my_display_name(text) to authenticated;grant execute on function update_shared_note(uuid,text,text) to authenticated;grant execute on function trash_shared_note(uuid) to authenticated;grant execute on function restore_shared_note(uuid) to authenticated;grant execute on function restore_note_revision(uuid) to authenticated;grant execute on function send_admin_notification(uuid,text,text) to authenticated;
alter publication supabase_realtime add table public.board_posts;alter publication supabase_realtime add table public.direct_messages;
